using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckCheeseRolling {
public enum CheesePhase {Countdown,HeadStart,Racing,Result,Complete,Settling}
[DefaultExecutionOrder(-100)]public sealed class CheeseMatch:MonoBehaviour {
 LWS.TruckSports.SportsParticipantBinding participantBinding;string participantMatchId;
 public void RefreshParticipants(bool saveEdits=false){if(participantBinding==null||!participantBinding.Matches(setup.players))participantBinding=new LWS.TruckSports.SportsParticipantBinding(setup.players);else participantBinding.Refresh(saveEdits);}
 void RecordParticipants(string summary,int count){LWS.TruckSports.SportsParticipantRegistry.Record(participantMatchId,SetupKey,summary,setup.players,count);}

 public const string SetupKey="TruckCheeseRolling.Setup.v1";
 public BowlingSetup setup=new BowlingSetup();public CheeseTruck[] trucks;public CheeseWheel cheese;public CheeseSheep[] sheep;public CheeseCamera[] cameras;public CheeseWeather weather;public CheeseMenus menus;public CheeseScenery scenery;public CheeseLook look;public int[] Grid{get;private set;}public SportsSettings settings;public SportsFeedback feedback;public ParticleSystem[] explosions;public CheeseDebris[] debris;
 public int seed=8137;public bool fixedSeed;public float headStart=.9f;public float startJump=5,startForward=4;public bool Starting=>InMatch&&(Phase==CheesePhase.Countdown||Phase==CheesePhase.HeadStart);public float StartElapsed=>Phase==CheesePhase.Settling?0:Starting?timer:3;public bool BoostReady(int i)=>startBoosts[i].Armed;public bool InMatch{get;private set;}public bool Paused{get;private set;}public bool Finished=>Phase==CheesePhase.Complete;public bool Live=>InMatch&&!Paused&&Phase==CheesePhase.Racing;public CheesePhase Phase{get;private set;}public int Round{get;private set;}public int Countdown=>Mathf.Max(1,Mathf.CeilToInt(3-timer));public int ModalOwner{get;private set;}public float RaceTime{get;private set;}public float Elapsed{get;private set;}public string Notice{get;private set;}="";public int[] totals=new int[4];public int Winner{get;private set;}=-1;public int Catches{get;private set;}public int NeutralReplays{get;private set;}public int BackgroundContacts{get;private set;}public int ExplosionCount{get;private set;}public int DamageApplications{get;private set;}public int WeatherMask{get;private set;}
 readonly CheeseStartBoost[] startBoosts=new CheeseStartBoost[16];readonly float[] aiThrottleAt=new float[16];int startBeat;readonly SportsDeviceInput input=new SportsDeviceInput();readonly Queue<CheeseSheep> blastQueue=new Queue<CheeseSheep>(48);uint contacts;float timer,lastProgress,bestDistance,blastSoundAt;int gateFrame,effectIndex;bool menuReleased;
 public bool Ready(int i){var p=setup.players[i];return p.source==BowlingSource.AI||p.source==BowlingSource.Keyboard&&Keyboard.current!=null&&Keyboard.current.enabled||p.Controller&&p.pad!=null&&p.pad.added&&p.pad.enabled;}
 public bool DevicesReady{get{if(!setup.Validate(out _))return false;for(int i=0;i<setup.count;i++)if(!Ready(i))return false;return true;}}
 public void Dirty(){menus.Dirty();}public void Save(){RefreshParticipants(true);setup.mode=BowlingMode.Simultaneous;LWS.TruckSports.SportsPrefs.SetString(SetupKey,JsonUtility.ToJson(setup));LWS.TruckSports.SportsPrefs.Save();Dirty();}
 void Awake(){try{if(LWS.TruckSports.SportsPrefs.HasKey(SetupKey)){var s=JsonUtility.FromJson<BowlingSetup>(LWS.TruckSports.SportsPrefs.GetString(SetupKey));if(s!=null&&s.players!=null&&s.players.Length==8)setup=s;}}catch(Exception){Debug.LogWarning("Cheese setup invalid; defaults restored.");}setup.count=Mathf.Clamp(setup.count,1,4);setup.mode=BowlingMode.Simultaneous;}
 void Start(){RefreshParticipants();Layout();menus.Show(CheeseScreen.Setup);}
 void OnEnable(){InputSystem.onDeviceChange+=Changed;}void OnDisable(){InputSystem.onDeviceChange-=Changed;feedback.StopAll();}void OnDestroy(){Time.timeScale=1;}
 public void AllAI(){for(int i=0;i<setup.count;i++){setup.players[i].source=BowlingSource.AI;setup.players[i].pad=null;}Save();}
 public bool Assign(int i,Gamepad pad){if(i<0||i>=setup.count||!setup.players[i].Controller||pad==null||!pad.added||!pad.enabled)return false;var old=setup.players[i].pad;setup.players[i].pad=pad;if(!setup.Validate(out _)){setup.players[i].pad=old;return false;}Gate();Dirty();return true;}
 public void Unassign(int i){setup.players[i].pad=null;Gate();Dirty();}
 public void NextPad(int i){var pads=Gamepad.all;for(int p=0;p<pads.Count;p++)if(pads[p]!=setup.players[i].pad&&Assign(i,pads[p]))return;Unassign(i);}
 public void CycleSource(int i){var p=setup.players[i];p.source=(BowlingSource)(((int)p.source+1)%5);p.pad=null;Save();}
 public Vector2 Drive(int i){var p=setup.players[i];if(p.source==BowlingSource.AI||!Ready(i))return Vector2.zero;if(p.source==BowlingSource.Keyboard)return new Vector2((SportsDeviceInput.KeyHeld(p.right)?1:0)-(SportsDeviceInput.KeyHeld(p.left)?1:0),(SportsDeviceInput.KeyHeld(p.forward)?1:0)-(SportsDeviceInput.KeyHeld(p.back)?1:0));if(p.source==BowlingSource.LeftStick||p.source==BowlingSource.RightStick){var v=p.source==BowlingSource.LeftStick?p.pad.leftStick.ReadValue():p.pad.rightStick.ReadValue();return new Vector2(Mathf.Abs(v.x)<.16f?0:Mathf.Clamp(v.x*settings.sensitivity,-1,1),Mathf.Abs(v.y)<.16f?0:v.y);}return new Vector2(Mathf.Clamp(p.pad.leftStick.x.ReadValue()*settings.sensitivity,-1,1),p.pad.rightTrigger.ReadValue()-p.pad.leftTrigger.ReadValue());}
 bool Neutral(int i){if(setup.players[i].source==BowlingSource.AI)return true;if(!Ready(i))return false;var p=setup.players[i];return Drive(i).sqrMagnitude<.01f&&(!p.Controller||!p.pad.buttonSouth.isPressed&&!p.pad.buttonEast.isPressed&&!p.pad.buttonWest.isPressed&&!p.pad.buttonNorth.isPressed&&!p.pad.startButton.isPressed&&p.pad.leftStick.ReadValue().magnitude<.16f&&p.pad.rightStick.ReadValue().magnitude<.16f);}

 public bool StartMatch(){if(!DevicesReady){menus.Show(CheeseScreen.Join);return false;}Save();participantMatchId=System.Guid.NewGuid().ToString("N");if(!fixedSeed)seed=UnityEngine.Random.Range(1,1000000);InMatch=true;Paused=false;Round=1;Elapsed=0;Catches=NeutralReplays=BackgroundContacts=ExplosionCount=DamageApplications=WeatherMask=0;Array.Clear(totals,0,4);Time.timeScale=1;Layout();NewRound();Gate();menus.Show(CheeseScreen.Play);return true;}
 public void Gate(){foreach(var p in setup.players)p.released=false;foreach(var t in trucks)t.command=Vector2.zero;gateFrame=Time.frameCount;menuReleased=false;}
 public bool MenuConfirm(){if(!InMatch||Finished)return true;return menuReleased&&(Mouse.current!=null&&Mouse.current.leftButton.wasReleasedThisFrame||SportsDeviceInput.KeyDown(Key.Enter)||SportsDeviceInput.KeyDown(Key.Space)||setup.players[ModalOwner].Controller&&Ready(ModalOwner)&&setup.players[ModalOwner].pad.buttonSouth.wasPressedThisFrame);}
 public void Pause(int owner=0,bool disconnected=false){if(!InMatch||Finished)return;ModalOwner=Mathf.Clamp(owner,0,setup.count-1);Paused=true;Time.timeScale=0;Gate();feedback.StopAll();foreach(var t in trucks)t.StopSound();weather.Pause(true);menus.Show(disconnected?CheeseScreen.Join:CheeseScreen.Pause);}
 public void Resume(){if(!InMatch){StartMatch();return;}if(!DevicesReady){menus.Show(CheeseScreen.Join);return;}Paused=false;Time.timeScale=1;Gate();weather.Pause(false);menus.Show(CheeseScreen.Play);}
 public void ChangeSetup(){InMatch=Paused=false;Time.timeScale=1;feedback.StopAll();foreach(var t in trucks)t.Hold();cheese.body.isKinematic=true;menus.Show(CheeseScreen.Setup);}
 public void Layout(){var owners=new int[4];int count=InMatch?SportsCameraOptions.SelectOrSpectate(setup,owners):1;if(!InMatch)owners[0]=0;weather.vendor.AllowCameras.Clear();for(int slot=0;slot<4;slot++){int view=Array.IndexOf(owners,slot,0,count);bool visible=view>=0;var rect=LWS.TruckCornhole.CornholeMatch.ViewRect(count,Mathf.Max(0,view));cameras[slot].view.rect=rect;cameras[slot].view.enabled=visible;menus.LayoutView(slot,rect,visible);cameras[slot].ResetView();if(visible)weather.vendor.AllowCameras.Add(cameras[slot].view);}}
 void Changed(InputDevice d,InputDeviceChange c){if(SportsFocusPolicy.Suspended(d,c))return;Dirty();if(!InMatch||Finished)return;for(int i=0;i<setup.count;i++)if(setup.players[i].pad==d){input.Forget((Gamepad)d);Gate();if(c==InputDeviceChange.Removed||c==InputDeviceChange.Disconnected||c==InputDeviceChange.Disabled)Pause(i,true);break;}}
 void OnApplicationFocus(bool focus){if(!focus)feedback.StopAll();}
 public void Pulse(int slot,float strength,float seconds){var p=setup.players[slot];if(p.source==BowlingSource.WholeController)feedback.Pulse(p.pad,strength,seconds);}
 public void Catch(CheeseTruck t){if(!Live)return;if(!t.Scoring){BackgroundContacts++;return;}if(t.CatchArmed)contacts|=1u<<t.index;}
 void NewRound(){blastQueue.Clear();contacts=0;timer=RaceTime=lastProgress=0;startBeat=0;Array.Clear(startBoosts,0,startBoosts.Length);var startRandom=new System.Random(seed+Round*3571);for(int i=0;i<16;i++){int difficulty=i<setup.count?(int)setup.players[i].difficulty:1;aiThrottleAt[i]=1.45f+((float)startRandom.NextDouble()-.5f)*(difficulty==0?2.6f:difficulty==1?1.5f:.7f);}bestDistance=9999;Winner=-1;Phase=CheesePhase.Settling;weather.Select(seed+Round-1);WeatherMask|=1<<(int)weather.Kind;Notice="ONLY MARKED RACERS SCORE · "+weather.Kind.ToString().ToUpper();cheese.body.isKinematic=false;cheese.body.position=CheeseRules.Surface(Mathf.Sin((seed+Round)*.73f)*2,27,2);cheese.body.rotation=Quaternion.Euler(0,0,90);cheese.body.linearVelocity=cheese.body.angularVelocity=Vector3.zero;cheese.body.isKinematic=true;
  scenery.Randomize(seed+Round*977);Grid=CheeseRules.StarterGrid(seed,Round);var block=new MaterialPropertyBlock();for(int i=0;i<trucks.Length;i++){bool active=i<setup.count||i>=4;var t=trucks[i];t.gameObject.SetActive(active);if(!active)continue;int slot=Grid[i];float x=(slot%8-3.5f)*10,z=slot<8?8:-4;t.ResetTruck(CheeseRules.Surface(x,z,t.StartLift),Quaternion.identity);block.SetColor("_BaseColor",i<setup.count?setup.players[i].color:Color.HSVToRGB((i*.137f)%1,.55f,.65f));t.paint.SetPropertyBlock(block);t.marker.gameObject.SetActive(i<setup.count);if(i<setup.count)t.marker.GetComponent<TMPro.TMP_Text>().text="P"+(i+1);}
  var rng=new System.Random(seed+Round*977);foreach(var s in sheep){float x,z;int attempts=0;do{x=(float)(rng.NextDouble()*82-41);z=(float)(rng.NextDouble()*215+40);attempts++;}while(attempts<30&&(z<60&&Mathf.Abs(x)<12));s.ResetHazard(CheeseRules.Surface(x,z,.8f));}foreach(var bit in debris){bit.body.isKinematic=true;bit.gameObject.SetActive(false);}foreach(var fx in explosions)fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);Physics.SyncTransforms();foreach(var c in cameras)c.ResetView();Dirty();
 }
 public bool SafeRecovery(Vector3 p,CheeseTruck self){if(!scenery.ClearAt(p,2.5f))return false;foreach(var t in trucks)if(t!=self&&t.gameObject.activeSelf&&Vector3.Distance(t.body.position,p)<3)return false;foreach(var s in sheep)if(s.gameObject.activeSelf&&Vector3.Distance(s.transform.position,p)<(s.Queued?26:7))return false;foreach(var fx in explosions)if(fx.isPlaying&&Vector3.Distance(fx.transform.position,p)<24)return false;return true;}
 public float HazardSteer(Vector3 p,float caution){float steer=scenery.Avoid(p);foreach(var s in sheep)if(s.gameObject.activeSelf){var d=s.transform.position-p;if(d.z>0&&d.z<12&&Mathf.Abs(d.x)<caution)steer-=Mathf.Sign(d.x)*caution;}return Mathf.Clamp(steer,-8,8);}
 public void QueueBlast(CheeseSheep s){blastQueue.Enqueue(s);}
 public void Explode(Vector3 p){ExplosionCount++;var fx=explosions[effectIndex++%explosions.Length];fx.transform.position=p;fx.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);fx.Play();if(Time.time>=blastSoundAt){blastSoundAt=Time.time+.15f;feedback.Play(2,0,true);}
  for(int d=0;d<3;d++)debris[(ExplosionCount*3+d)%debris.Length].Emit(p+Vector3.up*(1+d*.2f)+Vector3.right*(d-1));foreach(var bit in debris)if(bit.gameObject.activeSelf&&Vector3.Distance(bit.body.position,p)<25)Impulse(bit.body,p,20);
  foreach(var tree in scenery.trees)if(tree.gameObject.activeSelf&&Vector3.Distance(tree.body.worldCenterOfMass,p)<25)tree.Blast(p);
  foreach(var t in trucks)if(t.gameObject.activeSelf){float d=Vector3.Distance(t.body.worldCenterOfMass,p);if(d>25)continue;float delta=Mathf.Lerp(26,2,Mathf.Clamp01((d-4)/21));Impulse(t.body,p,delta);t.Blast(p,delta,ExplosionCount);DamageApplications++;}if(Vector3.Distance(cheese.body.position,p)<25)Impulse(cheese.body,p,12);foreach(var s in sheep)if(s.gameObject.activeSelf&&Vector3.Distance(s.transform.position,p)<13)s.Queue();
 }
 static void Impulse(Rigidbody b,Vector3 p,float delta){if(b.isKinematic)return;var d=b.worldCenterOfMass-p;d.y=Mathf.Max(1.5f,d.y+4);b.AddForce(d.normalized*delta,ForceMode.VelocityChange);b.AddTorque(new Vector3(delta*.13f,delta*.08f,delta*.17f),ForceMode.VelocityChange);}
 void EndRound(int winner,string message){Debug.Log("CHEESE_ROUND_RESULT round="+Round+" winner="+winner+" "+message);contacts=0;Winner=winner;timer=0;Phase=CheesePhase.Result;Notice=message;if(winner>=0){totals[winner]++;Catches++;feedback.Play(4,0,true);Pulse(winner,.4f,.3f);}else NeutralReplays++;feedback.StopMotors();Dirty();}
 void FixedUpdate(){if(!InMatch||Paused||Finished)return;float dt=Time.fixedDeltaTime;timer+=dt;
  if(Phase==CheesePhase.Settling){bool ready=true;foreach(var t in trucks)if(t.gameObject.activeSelf)ready&=t.SettleOnGrid(dt);if(ready&&timer>=.45f){Phase=CheesePhase.Countdown;timer=0;Notice="";}else if(timer>6){ChangeSetup();Debug.LogError("Cheese starter suspension did not settle; race cancelled safely.");}return;}
  Elapsed+=dt;
  if(Starting){int beat=Mathf.Clamp(Mathf.FloorToInt(timer)+1,1,4);if(beat!=startBeat){startBeat=beat;feedback.Play(beat==4?5:4,0,true);}for(int i=0;i<trucks.Length;i++){if(!trucks[i].gameObject.activeSelf)continue;bool ai=i>=setup.count||setup.players[i].source==BowlingSource.AI;bool held=ai?timer>=aiThrottleAt[i]:setup.players[i].released&&trucks[i].command.y>.5f;startBoosts[i].Sample(Mathf.Min(timer,2.999f),held);}if(Phase==CheesePhase.Countdown&&timer>=3-Mathf.Clamp(headStart,0,1)){Phase=CheesePhase.HeadStart;cheese.body.isKinematic=false;cheese.body.WakeUp();Notice="CHEESE AWAY!";}if(timer>=3){Phase=CheesePhase.Racing;timer=0;Notice="GO! · CHASE THE CHEESE";foreach(var t in trucks)if(t.gameObject.activeSelf){t.Release();if(startBoosts[t.index].Armed){t.StartJump(startJump,startForward);if(t.Scoring)Pulse(t.index,.35f,.2f);}}}return;}
  if(Phase==CheesePhase.Result){if(timer>=3){if(Winner>=0&&totals[Winner]>=CheeseRules.Target){Phase=CheesePhase.Complete;RecordParticipants("Catches: "+LWS.TruckSports.SportsParticipantRegistry.Totals(setup.players,setup.count,i=>totals[i]),setup.count);feedback.StopAll();feedback.Play(5,0,true);menus.Show(CheeseScreen.Result);}else{Round++;NewRound();}}return;}
  RaceTime+=dt;if(contacts!=0){int winner=CheeseRules.Resolve(contacts,setup.count);EndRound(winner,winner==-2?"SIMULTANEOUS CATCH · NEUTRAL REPLAY":setup.count==1?"CATCH "+(totals[0]+1)+" / 5":setup.players[winner].name+" CAUGHT THE CHEESE");return;}
  for(int b=0;b<2&&blastQueue.Count>0;b++)blastQueue.Dequeue().Detonate();
  if(!CheeseRules.Safe(cheese.body.position)){EndRound(-1,"CHEESE UNREACHABLE · NEUTRAL REPLAY");return;}
  float closest=9999;foreach(var t in trucks)if(t.Scoring&&t.gameObject.activeSelf)closest=Mathf.Min(closest,Vector3.Distance(t.body.position,cheese.body.position));if(closest<bestDistance-.5f){bestDistance=closest;lastProgress=RaceTime;}if(RaceTime-lastProgress>110&&cheese.body.linearVelocity.sqrMagnitude<.04f||RaceTime>600)EndRound(-1,"NO REACHABLE PROGRESS · NEUTRAL REPLAY");
 }
 void Update(){input.Sample();if(menus.Screen==CheeseScreen.Join)foreach(var pad in Gamepad.all)if(input.Down(pad,2))for(int i=0;i<setup.count;i++)if(setup.players[i].Controller&&!Ready(i)&&Assign(i,pad))break;
  if(!menuReleased&&Time.frameCount>gateFrame){bool neutral=!SportsDeviceInput.KeyHeld(Key.Enter)&&!SportsDeviceInput.KeyHeld(Key.Space)&&(Mouse.current==null||!Mouse.current.leftButton.isPressed&&!Mouse.current.leftButton.wasReleasedThisFrame);for(int i=0;i<setup.count;i++)if(Ready(i))neutral&=Neutral(i);foreach(var p in Gamepad.all)neutral&=!p.buttonSouth.isPressed;if(neutral)menuReleased=true;}
  if(!InMatch||Finished)return;if(SportsDeviceInput.KeyDown(Key.Escape)){if(Paused){if(menuReleased)Resume();}else Pause();return;}for(int i=0;i<setup.count;i++){var p=setup.players[i];if(p.Controller&&Ready(i)&&input.Down(p.pad,4)){if(Paused){if(menuReleased)Resume();}else Pause(i);return;}}
  if(Paused)return;for(int i=0;i<setup.count;i++){var p=setup.players[i];if(p.source==BowlingSource.AI)continue;if(!Ready(i)){Pause(i,true);return;}if(!p.released){if(Neutral(i))p.released=true;continue;}trucks[i].command=Drive(i);if(Live&&p.source==BowlingSource.WholeController&&p.pad.buttonNorth.wasPressedThisFrame)trucks[i].Recover();}
 }
}
}
